    if (hor_pos < H_TOTAL) hor_pos <= hor_pos + 1;
    else hor_pos <= 0;

    if (hor_pos == H_FRONT-1) h_sync <= 1'b1;
    if (hor_pos == H_FRONT+H_SYNC-1) h_sync <= 1'b0;

