    if (ver_pos < V_TOTAL) ver_pos <= ver_pos + 1;
    else ver_pos <= 0;

    if (ver_pos == V_FRONT-1) v_sync <= 1'b1;
    if (ver_pos == V_FRONT+V_SYNC-1) v_sync <= 1'b0;

end
end

    //RGB Data
    always @(posedge clock) begin
    if (~aresetn)
    begin
    R <= 8'd0;
    B <= 8'd0;
    G <= 8'd0;
end
    else if ((hor_pos < H_BLANK) | (ver_pos < V_BLANK))
    begin
    R <= 8'd0;
    B <= 8'd0;
    G <= 8'd0;
end
    else
    begin
    if (color == 3'b100)
    begin
    R <= hor_pos[7:0];
    G <= ver_pos[7:0];
    B <= hor_pos[7:0];
end
    else if (color == 3'b110)
    begin
    R <= 8'd255;
    G <= 8'd0;
    B <= 8'd0;
end
    else if (color == 3'b101)
    begin
    R <= 8'd0;
    G <= 8'd255;
    B <= 8'd0;
end
    else if (color == 3'b011)
    begin
    R <= 8'd0;
    G <= 8'd0;
    B <= 8'd255;
end
    else
    begin
    R <= R;
    G <= G;
    B <= B;
end
end
end

