    module ripple_carry_adder (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [3:0] xor_output;
    wire [3:0] and_output;

    assign xor_output = A ^ B;
    assign and_output = A & B;

    assign Sum = xor_output ^ Cin;
    assign Cout = and_output | (xor_output & Cin);

